const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helper to promisify getInfo/evaluate
  const getInfo = (obj) => new Promise((resolve, reject) => obj.getInfo(resolve, reject));
  const evaluate = (obj) => new Promise((resolve, reject) => obj.evaluate(resolve, reject));

  // 1. Geometry & Time Definitions
  const cambodia = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', 'Cambodia'))
    .geometry();
  const startDate = '2014-01-01';
  const endDate = '2017-12-31';
  const years = [2014, 2015, 2016, 2017];

  // 2. Data Acquisition & Check
  let terraAll = ee.ImageCollection('MODIS/006/MOD14A1').filterDate(startDate, endDate).filterBounds(cambodia);
  let aquaAll  = ee.ImageCollection('MODIS/006/MYD14A1').filterDate(startDate, endDate).filterBounds(cambodia);
  let nTerra = await getInfo(terraAll.size());
  let nAqua  = await getInfo(aquaAll.size());

  if ((nTerra === 0 || nTerra === null) && (nAqua === 0 || nAqua === null)) {
    // Fallback to VIIRS 1km FireMask if MODIS daily not available (very unlikely)
    terraAll = ee.ImageCollection('NOAA/VIIRS/001/VNP14A1').filterDate(startDate, endDate).filterBounds(cambodia);
    aquaAll  = ee.ImageCollection('NOAA/VIIRS/001/VNP14A1').filterDate(startDate, endDate).filterBounds(cambodia);
    nTerra = await getInfo(terraAll.size());
    nAqua  = await getInfo(aquaAll.size());
    if ((nTerra === 0 || nTerra === null) && (nAqua === 0 || nAqua === null)) {
      console.log('Collections empty for both primary and fallback.');
      console.log('C1');
      return;
    }
  }
  console.log(`Images (2014-2017) Terra: ${nTerra}, Aqua: ${nAqua}`);

  // 3. Processing helpers
  function monthFireStats(year, month) {
    const start = ee.Date.fromYMD(year, month, 1);
    const end = start.advance(1, 'month');
    // Select FireMask band and monthly max composite for Terra and Aqua
    const terMax = terraAll.filterDate(start, end).select('FireMask').max();
    const aqMax  = aquaAll.filterDate(start, end).select('FireMask').max();
    // Combine by max to catch any detection
    const comb = ee.ImageCollection([terMax, aqMax]).max().rename('FireMaskMax');
    const fireImage = comb.gt(6).rename('fire'); // Fire if FireMask > 6
    const validCount = comb.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: cambodia,
      scale: 1000,
      maxPixels: 1e9
    }).get('FireMaskMax');
    const fireCount = fireImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: cambodia,
      scale: 1000,
      maxPixels: 1e9
    }).get('fire');
    return Promise.all([evaluate(validCount), evaluate(fireCount)]).then(([vc, fc]) => {
      return { valid: vc, fire: fc };
    });
  }

  // 4. Calculation across years for Feb and Oct
  let totals = { Feb: 0, Oct: 0 };
  let minValid = null;
  for (const y of years) {
    const feb = await monthFireStats(y, 2);
    const oct = await monthFireStats(y, 10);
    // Case 2: No valid pixels
    if ((feb.valid === 0 || feb.valid === null) && (oct.valid === 0 || oct.valid === null)) {
      console.log(`Year ${y} has 0 valid pixels in both months.`);
      console.log('C2');
      return;
    }
    // Case 3: Calculation Failure
    if ([feb.valid, feb.fire, oct.valid, oct.fire].some(v => v === null || Number.isNaN(v))) {
      console.log(`Year ${y} has null/NaN results.`);
      console.log('C3');
      return;
    }
    // Update min valid pixels tracker
    const localMin = Math.min(feb.valid || Infinity, oct.valid || Infinity);
    minValid = (minValid === null) ? localMin : Math.min(minValid, localMin);

    const febFire = feb.fire || 0;
    const octFire = oct.fire || 0;
    totals.Feb += febFire;
    totals.Oct += octFire;
    console.log(`${y} FebFirePx:${febFire} OctFirePx:${octFire}`);
  }

  console.log(`ValidPixMin:${minValid}`);
  console.log(`Totals Feb:${totals.Feb} Oct:${totals.Oct}`);

  // 5. Final Answer
  if (totals.Feb > totals.Oct) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (err) {
    console.log('D');
  }
}

initEE();
